import { openResearchProject } from './research-project-picker.mjs'
// Full authoring journey in Chromium: the product's real view and module loader.
import assert from 'node:assert/strict'
import { createRequire } from 'node:module'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
assert.ok(process.env.MC_PLAYWRIGHT_ROOT)
assert.ok(process.env.BENCHMARK_TEST_ORIGIN)
const { chromium } = createRequire(import.meta.url)(process.env.MC_PLAYWRIGHT_ROOT)
const out = resolve(process.env.BENCHMARK_TEST_OUTPUT || 'nesting-browser-evidence')
await mkdir(out, { recursive: true })
const browser = await chromium.launch({ headless: true }), errors = []
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 }, acceptDownloads: true })
  page.on('pageerror', error => errors.push(error.message))
  await page.goto(process.env.BENCHMARK_TEST_ORIGIN + '/#/research')
  await page.locator('button[data-research-area="design"]').click()
  const tip = page.getByRole('button', { name: 'Not now', exact: true })
  if (await tip.isVisible()) await tip.click()
  const f = name => page.locator(`[data-bench-${name}]`), n = name => page.locator(`[data-nest-${name}]`)
  const idle = () => page.waitForFunction(() => document.querySelector('[data-mc="benchmark"]').getAttribute('aria-busy') === 'false')
  await idle()
  assert.equal(await page.locator('button[data-research-area="all"]').count(), 0)
  await page.locator('[data-research-edit]').click()
  assert.equal(await page.locator('.research-page').getAttribute('data-research-area'), 'all')
  await page.locator('[data-research-edit]').click()
  assert.equal(await page.locator('.research-page').getAttribute('data-research-area'), 'design')
  await openResearchProject(page); await f('starter').selectOption('lean-bench-snippets-and-compositions'); await f('use-starter').click(); await idle()
  assert.deepEqual(await page.locator('.bench-steps button').evaluateAll(nodes => nodes.slice(0, 4).map(node => node.textContent)), ['Snippets', 'Composition', 'Nesting', 'Variance'])
  assert.deepEqual(await page.locator('.bench-steps button').evaluateAll(nodes => nodes.slice(0, 4).map(node => getComputedStyle(node, '::before').content)), ['"1. "', '"2. "', '"3. "', '"4. "'])
  const originalRouting = JSON.parse(await f('routing').inputValue())
  const containsComposition = node => !!node?.composition || Object.values(node?.slots || {}).some(containsComposition)
  const plainIndices = originalRouting.compositions.flatMap((item, index) => containsComposition(item.node) ? [] : [String(index)])
  assert.deepEqual(await f('routing-editor').locator('[data-routing-composition-name]').evaluateAll(nodes => nodes.map(node => node.dataset.routingCompositionName)), plainIndices, 'Composition retains snippet-built arrangements and omits only nested arrangements')
  await f('routing-editor').evaluate(node => node.scrollIntoView({ block: 'start' }))
  assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 2), 'Composition fits the viewport')
  await page.screenshot({ path: resolve(out, 'composition-restored.png') })
  await page.locator('[data-bench-tab="nesting"]').click()
  assert.equal(await page.locator('[data-bench-panel="nesting"]').isVisible(), true)
  assert.equal(await page.locator('[data-bench-panel="compose"]').isVisible(), false)
  await n('selected').selectOption('BL-08')
  assert.equal(await page.locator('.nesting-author').isVisible(), true, 'the original nesting builder remains visible')
  assert.equal(await page.locator('.nesting-inspection-grid').isVisible(), true, 'the original structure and prompt inspection stays below the builder')
  assert.equal(await n('connection-editor').locator('.routing-composition').count(), 1, 'one saved structure is editable at a time in Nesting')
  assert.ok(await page.locator('.nesting-outline [data-nest-branch][open]').count() > 1)
  assert.equal(await page.locator('.nesting-outline [data-nest-inspect="T1v0 / Strategy A"]').isVisible(), true)
  await n('search').fill('BL-08')
  assert.equal(await n('palette').locator('[data-nest-inspect]').count(), 2, 'the saved list remains searchable on Nesting')
  await page.locator('[data-bench-panel="nesting"]').evaluate(node => node.scrollIntoView({ block: 'start' }))
  await page.screenshot({ path: resolve(out, 'bl08-reader-desktop.png') })
  await page.locator('.nesting-outline [data-nest-inspect="T1v0 / Strategy A"]').click()
  assert.equal(await n('selected').inputValue(), 'T1v0 / Strategy A')
  await n('expand').click()
  await page.waitForFunction(() => document.querySelector('[data-nest-preview]').textContent.length > 10)
  assert.equal(await n('preview').isVisible(), true, 'the assembled wording remains beside its structure')
  await page.locator('[data-nest-back="0"]').click()
  await n('edit').click()
  assert.equal(await n('connections').getAttribute('open'), '', 'imported structures retain their editable connections')
  const blIndex = originalRouting.compositions.findIndex(item => item.name === 'BL-08')
  await n('connection-editor').locator(`[data-routing-use="${blIndex}:strategy_b"]`).selectOption('composition:T1v0 / Strategy A')
  assert.equal(JSON.parse(await f('routing').inputValue()).compositions[blIndex].node.slots.strategy_b.composition, 'T1v0 / Strategy A')
  await n('connection-editor').locator(`[data-routing-use="${blIndex}:strategy_b"]`).selectOption('composition:BL-08 / Strategy B')
  assert.deepEqual(JSON.parse(await f('routing').inputValue()), originalRouting, 'browsing and reverting a connection preserve the original graph')
  await n('selected').selectOption('BL-08')
  await page.setViewportSize({ width: 850, height: 1000 })
  assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 2))
  await page.locator('.nesting-inspector').evaluate(node => node.scrollIntoView({ block: 'start' }))
  await page.screenshot({ path: resolve(out, 'bl08-reader-narrow.png') })
  await page.setViewportSize({ width: 1440, height: 1100 })
  await n('new').click()
  for (const name of ['T1v0 / Strategy A', 'O1v0 / Strategy', 'BL-08 / Strategy B']) {
    await n('search').fill(name)
    await n('palette').getByRole('button', { name: 'Add ' + name, exact: true }).click()
  }
  assert.equal(await page.locator('[data-nest-member]').count(), 3)
  await n('name').fill('Cross-family conditional trio')
  await n('mode').selectOption('conditional-all')
  await n('instructions').fill('Use the declared data. Preserve the meaning of each selected member.')
  await page.locator('[data-nest-condition="0"]').fill('The equity signal holds.')
  await page.locator('[data-nest-condition="1"]').fill('The options signal holds.')
  await page.locator('[data-nest-condition="2"]').fill('The second equity signal holds.')
  await page.locator('[data-nest-up="2"]').click()
  assert.equal(await page.locator('[data-nest-member="1"]').inputValue(), 'BL-08 / Strategy B')
  await n('preview-form').click()
  await page.waitForFunction(() => document.querySelector('[data-nest-preview-note]').textContent.includes('Unsaved nesting preview'))
  assert.match(await n('preview').textContent(), /More than one member may apply/)
  assert.match(await n('preview').textContent(), /options signal/)
  await n('instructions').fill('Use the declared data. Preserve each member. Report which conditions held.')
  assert.match(await n('preview-note').textContent(), /Nesting changed/)
  await n('preview-form').click()
  await page.waitForFunction(() => document.querySelector('[data-nest-preview-note]').textContent.includes('Unsaved nesting preview'))
  assert.match(await n('preview').textContent(), /Report which conditions held/)
  await n('save').click(); await idle()
  assert.match(await n('status').textContent(), /Composition saved/)
  assert.equal(await n('selected').inputValue(), 'Cross-family conditional trio')
  assert.equal(await f('task').locator('option').count(), 41, 'saving a composition does not replace tasks')
  await n('task').click(); await idle()
  assert.equal(await f('task').locator('option').count(), 42)
  await n('new').click()
  await n('search').fill('Cross-family conditional trio')
  await n('palette').getByRole('button', { name: 'Add Cross-family conditional trio', exact: true }).click()
  await n('search').fill('O1v0')
  await n('palette').getByRole('button', { name: 'Add O1v0', exact: true }).click()
  await n('name').fill('Outer experiment'); await n('mode').selectOption('sequence')
  await n('save').click(); await idle()
  assert.match(await n('status').textContent(), /Composition saved/)
  await page.locator('.nesting-outline [data-nest-inspect="Cross-family conditional trio"]').click()
  assert.equal(await n('selected').inputValue(), 'Cross-family conditional trio')
  assert.match(await page.locator('.nesting-breadcrumbs').textContent(), /Outer experiment/)
  await page.locator('[data-nest-back="0"]').click()
  assert.equal(await n('selected').inputValue(), 'Outer experiment')
  await n('new').click(); await n('name').fill('Unfinished arrangement')
  await n('add-empty').click()
  const wait = page.waitForEvent('download'); await f('draft-export').click()
  const download = await wait, file = resolve(out, 'nested-draft.json'); await download.saveAs(file)
  const draft = JSON.parse(await readFile(file, 'utf8')), routing = JSON.parse(draft.editors['data-bench-routing'])
  assert.equal(draft.spec.tasks.length, 42)
  assert.equal(routing.compositions.find(item => item.name === 'Outer experiment').node.slots.member_1.composition, 'Cross-family conditional trio')
  assert.equal(JSON.parse(draft.editors['data-bench-nesting-draft']).form.name, 'Unfinished arrangement')
  await f('new-empty').click(); await idle()
  await openResearchProject(page); await f('import').setInputFiles(file); await idle()
  await page.locator('[data-bench-tab="nesting"]').click()
  assert.equal(await n('name').inputValue(), 'Unfinished arrangement')
  assert.equal(await n('selected').inputValue(), 'Outer experiment')
  await n('selected').selectOption('Cross-family conditional trio')
  await n('edit').click()
  assert.equal(await page.locator('[data-nest-member]').count(), 3)
  assert.equal(await page.locator('[data-nest-condition="1"]').inputValue(), 'The second equity signal holds.')
  await page.locator('[data-bench-panel="nesting"]').evaluate(node => node.scrollIntoView({ block: 'start' }))
  await page.screenshot({ path: resolve(out, 'nesting-desktop.png') })
  await page.setViewportSize({ width: 850, height: 1000 })
  assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 2), 'the nesting page fits a narrow viewport')
  await page.screenshot({ path: resolve(out, 'nesting-narrow.png') })
  await n('from-snippets').click()
  const newIndex = originalRouting.compositions.length + 2
  const nameInput = n('connection-editor').locator(`[data-routing-composition-name="${newIndex}"]`)
  await nameInput.fill(''); await nameInput.press('Tab')
  assert.equal(JSON.parse(await f('routing').inputValue()).compositions[newIndex].name, 'Untitled composition 1', 'an empty rename cannot orphan a saved structure')
  await nameInput.fill('A small reusable prompt'); await nameInput.press('Tab')
  const catalog = draft.spec.catalog, leaf = catalog.find(item => item.kind === 'atom')
  await n('connection-editor').locator(`[data-routing-use="${newIndex}:"]`).selectOption('snippet:' + leaf.id)
  assert.equal(await n('selected').inputValue(), 'A small reusable prompt')
  assert.equal(JSON.parse(await f('routing').inputValue()).compositions[newIndex].node.use, leaf.id)
  await n('connection-editor').locator(`[data-routing-remove-composition="${newIndex}"]`).click()
  assert.equal(JSON.parse(await f('routing').inputValue()).compositions.length, newIndex, 'a new snippet-based composition can be removed')
  await page.locator('[data-bench-tab="compose"]').click()
  await page.locator('[data-routing-capture]').click(); await idle()
  assert.equal(await page.locator('[data-bench-panel="compose"]').isVisible(), true, 'copying a task keeps its snippet-built arrangement in Composition')
  assert.ok((await f('routing-editor').locator('[data-routing-composition-name]').evaluateAll(nodes => nodes.map(node => node.value))).includes('Untitled composition 1'))
  assert.equal(await f('task').locator('option').count(), 42)
  assert.deepEqual(errors, [])
  const result = { pass: true, compositionBeforeNesting: true, originalNestingLayout: true, allModulesButtonRemoved: true, layoutReturnsToPage: true, importedConnectionsEditable: true, crossFamilyMembers: 3, nestedAgain: true, taskCount: 42, originalTasksPreserved: true, conditionalOrder: true, importedUnfinishedDraft: true, traceNavigation: true, errors }
  await writeFile(resolve(out, 'results.json'), JSON.stringify(result, null, 2) + '\n')
  console.log(JSON.stringify(result))
} finally { await browser.close() }
